// Writes js/data.bundle.js: every data file in one script, so the app also runs from file://.
// Run after any change in data/ or samples/:  node tools/bundle_data.js
'use strict';
const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');

function readJSON(rel) {
  return JSON.parse(fs.readFileSync(path.join(ROOT, rel), 'utf8'));
}

function buildBundle() {
  const sections = readJSON('data/sections/index.json');
  const templates = {};
  sections.sections.forEach((s) => {
    if (s.template && !templates[s.template]) templates[s.template] = readJSON('data/sections/' + s.template);
  });
  const data = {
    drivers: readJSON('data/drivers.json'),
    survey: readJSON('data/survey.json'),
    keywords: readJSON('data/keywords.json'),
    rules: readJSON('data/rules.json'),
    uniformat: readJSON('data/uniformat.json'),
    sections,
    templates,
    sample: readJSON('samples/sketch-project.json')
  };
  return (
    '// Generated by tools/bundle_data.js from data/ and samples/. Do not edit by hand.\n' +
    '(typeof window !== "undefined" ? window : globalThis).SS_DATA = ' +
    JSON.stringify(data, null, 1) + ';\n'
  );
}

if (require.main === module) {
  fs.writeFileSync(path.join(ROOT, 'js/data.bundle.js'), buildBundle());
  console.log('wrote js/data.bundle.js');
}

module.exports = { buildBundle, ROOT };
